import { Group, Mesh, PlaneGeometry, MeshStandardMaterial, Color, Texture } from 'three/webgpu';
import { nodes } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Array} cinematicPrimitives
 * @property {Object} textContent
 * @property {Object} visual
 * @property {Object} placement
 * @property {Object} colors
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} primitives
 * @property {Object} fontAtlas - { texture: Texture, getGlyphInfo: (char:string)=>{width:number,height:number,u0:number,v0:number,u1:number,v1:number,advance:number} }
 * @property {Object} textureLoader
 */

/**
 * Helper: create a plane material for MSDF text using three/tsl nodes.
 * @param {Texture} atlas
 * @returns {MeshStandardMaterial}
 */
function createMSDFMaterial(atlas) {
    // basic signed distance field shader using tsl nodes
    const texNode = nodes.texture(atlas);
    const uvNode = nodes.uv();
    const sample = nodes.textureSample(texNode, uvNode);
    const sdf = nodes.luminance(sample);
    const smooth = nodes.smoothstep(0.5 - 0.1, 0.5 + 0.1, sdf);
    const opacity = smooth;
    const colorNode = nodes.mix(
        nodes.vec3(0.0, 0.0, 0.0), // ink (black)
        nodes.vec3(1.0, 1.0, 1.0), // white (unused)
        smooth
    );
    const material = new MeshStandardMaterial({
        transparent: true,
        depthWrite: false,
        side: 2 // DoubleSide
    });
    material.color = new Color(0x16161d);
    material.opacity = 1.0;
    material.map = atlas;
    material.toneMapped = false;
    // attach node material (tsl) – the API expects .nodeMaterial property
    material.nodeMaterial = nodes.standardMaterial({
        color: colorNode,
        opacity: opacity,
        map: texNode
    });
    return material;
}

/**
 * Helper: build a text group from a string.
 * @param {string} text
 * @param {Object} opts
 * @param {number} opts.emHeight - desired height in scene units for the em square.
 * @param {number} opts.letterSpacing - additional spacing (scene units).
 * @param {number} opts.lineHeight - multiplier.
 * @param {Texture} atlas
 * @returns {Group}
 */
function buildTextGroup(text, { emHeight, letterSpacing = 0, lineHeight = 1 }, atlas) {
    const group = new Group();
    const material = createMSDFMaterial(atlas);
    const glyphInfos = [];
    let totalAdvance = 0;
    for (let i = 0; i < text.length; i++) {
        const ch = text[i];
        const info = ctx.fontAtlas.getGlyphInfo(ch);
        if (!info) continue;
        glyphInfos.push({ ch, info, index: i });
        totalAdvance += info.advance + letterSpacing;
    }
    const scale = emHeight / atlas.userData.emSize; // assume atlas stores original em size
    let cursor = -totalAdvance * scale * 0.5;
    glyphInfos.forEach(({ ch, info }) => {
        const width = info.width * scale;
        const height = info.height * scale;
        const geometry = new PlaneGeometry(width, height);
        // set UVs manually
        const uvs = geometry.attributes.uv.array;
        uvs[0] = info.u0; uvs[1] = info.v1;
        uvs[2] = info.u1; uvs[3] = info.v1;
        uvs[4] = info.u0; uvs[5] = info.v0;
        uvs[6] = info.u1; uvs[7] = info.v0;
        geometry.attributes.uv.needsUpdate = true;

        const mesh = new Mesh(geometry, material);
        mesh.position.set(cursor + width * 0.5, 0, 0);
        group.add(mesh);
        cursor += (info.advance + letterSpacing) * scale;
    });
    group.scale.set(1, lineHeight, 1);
    return group;
}

/**
 * Main exported creator.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Group}
 */
export default function createNode(config, ctx) {
    const root = new Group();
    root.position.set(
        config.placement?.position?.[0] ?? 0,
        config.placement?.position?.[1] ?? 0,
        config.placement?.position?.[2] ?? 0
    );
    root.rotation.set(
        config.placement?.rotation?.[0] ?? 0,
        config.placement?.rotation?.[1] ?? 0,
        config.placement?.rotation?.[2] ?? 0
    );
    root.scale.set(
        config.placement?.scale?.[0] ?? 1,
        config.placement?.scale?.[1] ?? 1,
        config.placement?.scale?.[2] ?? 1
    );

    // ---------- Backdrop ----------
    const backdropGeom = new PlaneGeometry(7, 5.5);
    const gradientTex = ctx.textureLoader.load('data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Z5M9zYAAAAASUVORK5CYII=');
    const backdropMat = new MeshStandardMaterial({
        map: gradientTex,
        transparent: true,
        side: 2,
        metalness: 0,
        roughness: 1,
        emissive: new Color(0x000000)
    });
    // Using tsl nodes to create engineered gradient (simple vertical lerp)
    const texNode = nodes.texture(gradientTex);
    const uvNode = nodes.uv();
    const gradNode = nodes.mix(
        nodes.vec3(0x0b0b10 / 255, 0x0b0b10 / 255, 0x0b0b10 / 255),
        nodes.vec3(0x13 / 255, 0x13 / 255, 0x1a / 255),
        uvNode.y
    );
    backdropMat.nodeMaterial = nodes.standardMaterial({ color: gradNode, map: texNode });
    const backdrop = new Mesh(backdropGeom, backdropMat);
    backdrop.position.set(0, 0, -1.5);
    root.add(backdrop);

    // ---------- Hero Text ----------
    const heroText = "TIME, MACHINED.";
    const heroGroup = buildTextGroup(heroText, {
        emHeight: 0.62,
        letterSpacing: -0.01,
        lineHeight: 1.05
    }, ctx.fontAtlas.texture);
    heroGroup.position.set(0, 0.4, 0);
    // Apply per‑word Z offsets
    const words = heroText.split(' ');
    let wordIdx = 0;
    let accumulatedX = 0;
    heroGroup.children.forEach((glyph, i) => {
        const ch = heroText[i];
        if (ch === ' ') {
            wordIdx++;
            accumulatedX = 0;
            return;
        }
        const offsetMap = [0.12, 0.0, -0.12];
        const zOff = offsetMap[wordIdx] ?? 0;
        glyph.position.z = zOff;
    });
    root.add(heroGroup);

    // ---------- Underline ----------
    const underlineGeom = new PlaneGeometry(2.6, 0.045);
    const underlineMat = new MeshStandardMaterial({
        color: new Color(0xff2a38),
        emissive: new Color(0xff2a38),
        emissiveIntensity: 1.2,
        transparent: true,
        side: 2,
        metalness: 0,
        roughness: 0.5
    });
    const underline = new Mesh(underlineGeom, underlineMat);
    underline.position.set(-1.3, 0.35, 0); // left anchored
    underline.scale.set(0, 1, 1);
    root.add(underline);

    // ---------- Subhead ----------
    const subheadText = "Every calibre begins as a solid billet.";
    const subheadGroup = buildTextGroup(subheadText, {
        emHeight: 0.2,
        letterSpacing: 0.02,
        lineHeight: 1.35
    }, ctx.fontAtlas.texture);
    subheadGroup.position.set(0, -0.65, 0);
    root.add(subheadGroup);

    // ---------- Caption ----------
    const captionText = "NOVA ATELIER / CALIBRE PROGRAM";
    const captionGroup = buildTextGroup(captionText, {
        emHeight: 0.09,
        letterSpacing: 0.12,
        lineHeight: 1.4
    }, ctx.fontAtlas.texture);
    captionGroup.position.set(0, 1.15, 0);
    root.add(captionGroup);

    // ---------- Animations ----------
    const timeline = gsap.timeline({ paused: true });
    // hero kinetic per‑glyph
    heroGroup.children.forEach((glyph, idx) => {
        const delay = idx * 0.06;
        timeline.from(glyph.position, {
            y: glyph.position.y + 0.35,
            duration: 0.7,
            ease: "cubic-bezier(0.215,0.61,0.355,1)",
            delay
        }, 0);
        timeline.from(glyph.material, {
            opacity: 0,
            duration: 0.7,
            ease: "cubic-bezier(0.215,0.61,0.355,1)",
            delay
        }, 0);
    });
    // underline after last glyph
    const lastGlyphEnd = (heroGroup.children.length - 1) * 0.06 + 0.7;
    timeline.to(underline.scale, {
        x: 1,
        duration: 0.5,
        ease: "cubic-bezier(0.25,0.46,0.45,0.94)",
        delay: lastGlyphEnd + 0.12
    }, 0);
    // weighted‑settle on group
    timeline.fromTo(root.scale, {
        x: 1.04,
        y: 1.04,
        z: 1.04
    }, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.9,
        ease: "cubic-bezier(0.165,0.84,0.44,1)"
    }, lastGlyphEnd);
    // subhead fade‑up
    timeline.from(subheadGroup.position, {
        y: subheadGroup.position.y + 0.2,
        duration: 0.5,
        ease: "cubic-bezier(0.25,0.46,0.45,0.94)"
    }, 0);
    timeline.from(subheadGroup.children.map(m => m.material), {
        opacity: 0,
        duration: 0.5,
        ease: "cubic-bezier(0.25,0.46,0.45,0.94)"
    }, 0);
    timeline.play();

    // ---------- Apply Cinematic Primitives ----------
    if (Array.isArray(config.cinematicPrimitives)) {
        config.cinematicPrimitives.forEach(prim => {
            const fn = ctx.primitives?.[prim.name];
            if (typeof fn === 'function') {
                fn(root, prim.params ?? {});
            }
        });
    }

    // ---------- UserData ----------
    root.userData.handlers = {};
    root.userData.cleanup = () => {
        timeline.kill();
        root.traverse(obj => {
            if (obj.geometry) obj.geometry.dispose();
            if (obj.material) {
                if (Array.isArray(obj.material)) {
                    obj.material.forEach(m => m.dispose());
                } else {
                    obj.material.dispose();
                }
            }
        });
    };

    return root;
}
